#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
6/9 当天 xlsx 输入档部署包
==========================
还原 6/9 的 1-1/1-2 客服对话 xlsx 到 input/
用法: python3 deploy_xlsx_0609.py
"""
import base64, os
TARGET = "/root/bi_dashboard/input"
os.makedirs(TARGET, exist_ok=True)
FILES = {
    '客服對話_1-1_2026-06-09_完整對話.xlsx': "",
    '客服對話_1-2_2026-06-09_完整對話.xlsx': "",
}
n = 0
for fn, b64 in FILES.items():
    with open(os.path.join(TARGET, fn), 'wb') as f:
        f.write(base64.b64decode(b64))
    print(f'  还原 {fn}')
    n += 1
print()
print('='*50)
print(f'✅ 已还原 {n} 个 xlsx → {TARGET}')
print('='*50)
